   186	  private static boolean isJarFile(File file) {
   187	    if (!file.isFile()) return false;
   188	    String name = file.getName();
   189	    if (name.endsWith(".jar") || name.endsWith(".zip")) return true;
   190	    if (name.endsWith(".class")) return false;
   191	    try (SeekableByteChannel channel = Files.newByteChannel(file.toPath())) {
   192	      long size = channel.size();
   193	      // The EOCD ZIP record has 22+n bytes depending on the length of the comment.
   194	      if (size < 22) return false;
   195	      int bufferSize = (int) Math.min(size & ~3, 1024);
   196	      channel.position(size - bufferSize);
   197	      ByteBuffer buffer = ByteBuffer.allocate(bufferSize).order(ByteOrder.LITTLE_ENDIAN);
   198	      int read = 0;
   199	      while (read < bufferSize) {
   200	        read += channel.read(buffer);
   201	      }
   202	      buffer.flip();
   203	      for (int pos = buffer.limit() - 22; pos >= 0; pos--) {
   204	        if (buffer.getInt(pos) == 0x06054b50) {
   205	          return true;
   206	        }
   207	      }
   208	    } catch (IOException e) {
   209	      DecompilerContext.getLogger().writeMessage("Could not determine if " + file + " contains a JAR file", IFernflowerLogger.Severity.WARN, e);
   210	    }
   211	    return false;
   212	  }
