   343	  public void loadAbstractMetadata(String string) {
   344	    for (String line : string.split("\n")) {
   345	      String[] pts = line.split(" ");
   346	      if (pts.length < 4) //class method desc [args...]
   347	        continue;
   348	      GenericMethodDescriptor desc = GenericMain.parseMethodSignature(pts[2]);
   349	      List<String> params = new ArrayList<>();
   350	      for (int x = 0; x < pts.length - 3; x++) {
   351	        for (int y = 0; y < desc.parameterTypes.get(x).stackSize; y++)
   352	            params.add(pts[x+3]);
   353	      }
   354	      this.abstractNames.put(pts[0] + ' '+ pts[1] + ' ' + pts[2], params);
   355	    }
   356	  }
