// Copyright 2000-2021 JetBrains s.r.o. Use of this source code is governed by the Apache 2.0 license that can be found in the LICENSE file.
package org.jetbrains.java.decompiler.struct;

import org.jetbrains.annotations.Nullable;
import org.jetbrains.java.decompiler.main.DecompilerContext;
import org.jetbrains.java.decompiler.main.extern.IBytecodeProvider;
import org.jetbrains.java.decompiler.main.extern.IContextSource;
import org.jetbrains.java.decompiler.main.extern.IFernflowerLogger;
import org.jetbrains.java.decompiler.main.extern.IFernflowerPreferences;
import org.jetbrains.java.decompiler.main.extern.IResultSaver;
import org.jetbrains.java.decompiler.main.plugins.PluginContext;
import org.jetbrains.java.decompiler.struct.attr.StructEnclosingMethodAttribute;
import org.jetbrains.java.decompiler.struct.attr.StructGeneralAttribute;
import org.jetbrains.java.decompiler.struct.attr.StructInnerClassesAttribute;
import org.jetbrains.java.decompiler.struct.gen.generics.GenericMain;
import org.jetbrains.java.decompiler.struct.gen.generics.GenericMethodDescriptor;
import org.jetbrains.java.decompiler.util.DataInputFullStream;

import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.channels.SeekableByteChannel;
import java.nio.file.Files;
import java.util.*;

public class StructContext {
  private static volatile StructClass SENTINEL_CLASS;
  private static final byte[] MISSING_BYTES = new byte[0];

  public enum DuplicateClassStrategy {
    FIRST, LAST, ERROR
  }

  public static DuplicateClassStrategy validateDuplicateClassStrategy(Object value) {
    String strategy = Objects.toString(value, "first").toLowerCase(Locale.ROOT);
    return switch (strategy) {
      case "first" -> DuplicateClassStrategy.FIRST;
      case "last" -> DuplicateClassStrategy.LAST;
      case "error" -> DuplicateClassStrategy.ERROR;
      default -> throw new IllegalArgumentException(
        "Invalid duplicate-class-strategy '" + value + "'; accepted values are: first, last, error");
    };
  }

  static StructClass getSentinel() {
    if (SENTINEL_CLASS == null) {
      synchronized (StructContext.class) {
        if (SENTINEL_CLASS == null) {
          try (final InputStream stream = StructContext.class.getResourceAsStream("StructContext.class")) {
            byte[] data = stream.readAllBytes();
            SENTINEL_CLASS = StructClass.create(new DataInputFullStream(data), false);
          } catch (final IOException ex) {
            throw new UncheckedIOException(ex);
          }
        }
      }
    }
    return SENTINEL_CLASS;
  }

  @SuppressWarnings("deprecation")
  private final IBytecodeProvider legacyProvider;
  private final IResultSaver saver;
  private final IDecompiledData decompiledData;
  private final Object resolutionLock = new Object();
  private final List<ContextUnit> units = new ArrayList<>();
  private final List<ContextUnit> lazyUnits = new ArrayList<>();
  private final Map<String, List<ContextUnit>> candidatesByClassName = new LinkedHashMap<>();
  private final Map<String, ContextUnit> selections = new HashMap<>();
  private final Map<String, StructClass> classes = new HashMap<>();
  private final Map<ContextUnit, Map<String, byte[]>> classBytes = new IdentityHashMap<>();
  private final Map<ContextUnit, Map<String, byte[]>> lazyProbes = new IdentityHashMap<>();
  private final Map<String, String> familyRoots = new HashMap<>();
  private final Map<String, String> familyTriggers = new HashMap<>();
  private final Map<String, ContextUnit> familyAnchors = new HashMap<>();
  private final Map<String, List<String>> abstractNames = new HashMap<>();
  private boolean familyIndexInitialized;
  private int nextOriginIndex;

  private final PluginContext pluginContext = new PluginContext();

  @SuppressWarnings("deprecation")
  public StructContext(IBytecodeProvider legacyProvider, IResultSaver saver, IDecompiledData decompiledData) {
    this.legacyProvider = legacyProvider;
    this.saver = saver;
    this.decompiledData = decompiledData;
  }

  public StructContext(IResultSaver saver, IDecompiledData decompiledData) {
    this.legacyProvider = null;
    this.saver = saver;
    this.decompiledData = decompiledData;
  }

  public @Nullable StructClass getClass(String name) {
    if (name == null) {
      return null;
    }

    synchronized (this.resolutionLock) {
      StructClass cached = this.classes.get(name);
      if (cached != null) {
        return cached == getSentinel() ? null : cached;
      }

      ContextUnit selected = selectOrigin(name);
      if (selected == null) {
        this.classes.put(name, getSentinel());
        return null;
      }

      try {
        DecompilerContext.getLogger().writeMessage(
          "Loading Class: " + name + " from " + originName(selected), IFernflowerLogger.Severity.INFO);
        byte[] bytes = getClassBytes(selected, name);
        if (bytes == null) {
          this.classes.put(name, getSentinel());
          return null;
        }
        StructClass clazz = StructClass.create(new DataInputFullStream(bytes), selected.isOwn());
        this.classes.put(name, clazz);
        if (!name.equals(clazz.qualifiedName)) {
          this.classes.put(clazz.qualifiedName, clazz);
          this.selections.put(clazz.qualifiedName, selected);
        }
        return clazz;
      } catch (IOException ex) {
        String message = "Failed to read class " + name + " from " + originName(selected);
        DecompilerContext.getLogger().writeMessage(message, IFernflowerLogger.Severity.ERROR, ex);
        throw new UncheckedIOException(message, ex);
      }
    }
  }

  public boolean hasClass(final String name) {
    if (name == null) {
      return false;
    }
    synchronized (this.resolutionLock) {
      return selectOrigin(name) != null;
    }
  }

  public List<StructClass> getOwnClasses() {
    synchronized (this.resolutionLock) {
      List<StructClass> result = new ArrayList<>();
      Set<String> seen = new LinkedHashSet<>();
      for (Map.Entry<String, List<ContextUnit>> entry : this.candidatesByClassName.entrySet()) {
        if (entry.getValue().stream().noneMatch(ContextUnit::isOwn)) {
          continue;
        }
        StructClass clazz = Objects.requireNonNull(this.getClass(entry.getKey()), () -> "Could not find class " + entry.getKey());
        ContextUnit selected = this.selections.get(entry.getKey());
        if (selected != null && selected.isOwn() && seen.add(clazz.qualifiedName)) {
          result.add(clazz);
        }
      }
      return List.copyOf(result);
    }
  }

  public void reloadContext() throws IOException {
    synchronized (this.resolutionLock) {
      List<ContextUnit> roots = this.units.stream().filter(ContextUnit::isRoot).toList();
      this.units.clear();
      this.lazyUnits.clear();
      this.candidatesByClassName.clear();
      this.abstractNames.clear();
      this.nextOriginIndex = 0;
      clearResolutionState();
      for (ContextUnit root : roots) {
        root.clear();
        addSpace(root.getSource(), root.isOwn(), true);
      }
    }
  }

  public void saveContext() {
    this.getOwnClasses();
    for (ContextUnit unit : List.copyOf(this.units)) {
      if (unit.isOwn()) {
        try {
          unit.save(this::getClass, name -> isSelectedOrigin(name, unit));
        } catch (final IOException ex) {
          DecompilerContext.getLogger().writeMessage("Failed to save data for context unit " + originName(unit), IFernflowerLogger.Severity.ERROR, ex);
        }
      }
    }
  }

  private boolean isSelectedOrigin(String name, ContextUnit unit) {
    synchronized (this.resolutionLock) {
      return selectOrigin(name) == unit;
    }
  }

  private static boolean isJarFile(File file) {
    if (!file.isFile()) return false;
    String name = file.getName();
    if (name.endsWith(".jar") || name.endsWith(".zip")) return true;
    if (name.endsWith(".class")) return false;
    try (SeekableByteChannel channel = Files.newByteChannel(file.toPath())) {
      long size = channel.size();
      if (size < 22) return false;
      int bufferSize = (int) Math.min(size & ~3, 1024);
      channel.position(size - bufferSize);
      ByteBuffer buffer = ByteBuffer.allocate(bufferSize).order(ByteOrder.LITTLE_ENDIAN);
      int read = 0;
      while (read < bufferSize) {
        read += channel.read(buffer);
      }
      buffer.flip();
      for (int pos = buffer.limit() - 22; pos >= 0; pos--) {
        if (buffer.getInt(pos) == 0x06054b50) {
          return true;
        }
      }
    } catch (IOException e) {
      DecompilerContext.getLogger().writeMessage("Could not determine if " + file + " contains a JAR file", IFernflowerLogger.Severity.WARN, e);
    }
    return false;
  }

  public void addSpace(File file, boolean isOwn) {
    if (file.isDirectory()) {
      addSpace(new DirectoryContextSource(this.legacyProvider, file), isOwn);
