   295	  private @Nullable ContextUnit selectOrigin(String className) {
   296	    ContextUnit cached = this.selections.get(className);
   297	    if (cached != null) {
   298	      return cached;
   299	    }
   300	    if (this.missingSelections.contains(className)) {
   301	      return null;
   302	    }
   303	
   304	    List<ContextUnit> candidates = eligibleCandidates(className);
   305	    if (candidates.isEmpty()) {
   306	      this.missingSelections.add(className);
   307	      return null;
   308	    }
   309	
   310	    List<ContextUnit> ownCandidates = candidates.stream().filter(ContextUnit::isOwn).toList();
   311	    if (!ownCandidates.isEmpty()) {
   312	      ensureFamilyIndex();
   313	      String familyRoot = this.familyRoots.get(className);
   314	      if (familyRoot != null) {
   315	        ContextUnit anchor = ensureFamilyAnchor(familyRoot);
   316	        ContextUnit anchorSelection = this.selections.get(className);
   317	        if (anchorSelection != null) {
   318	          return anchorSelection;
   319	        }
   320	        validateDuplicateBytes(className, ownCandidates, familyRoot);
   321	        if (ownCandidates.contains(anchor)) {
   322	          this.selections.put(className, anchor);
   323	          warnIfDiffering(className, ownCandidates, anchor, familyRoot);
   324	          return anchor;
   325	        }
   326	        throw familyConflict(familyRoot, className, anchor, ownCandidates);
   327	      }
   328	      ContextUnit selected = selectByStrategy(className, ownCandidates, null);
   329	      this.selections.put(className, selected);
   330	      return selected;
   331	    }
   332	
   333	    ContextUnit selected = selectByStrategy(className, candidates, null);
   334	    this.selections.put(className, selected);
   335	    return selected;
   336	  }
