   338	  private List<ContextUnit> eligibleCandidates(String className) {
   339	    List<ContextUnit> registered = this.candidatesByClassName.getOrDefault(className, List.of());
   340	    if (registered.stream().anyMatch(ContextUnit::isOwn)) {
   341	      return registered.stream().filter(ContextUnit::isOwn).sorted(Comparator.comparingInt(ContextUnit::getOriginIndex)).toList();
   342	    }
   343	
   344	    List<ContextUnit> libraries = new ArrayList<>(registered);
   345	    for (ContextUnit unit : this.lazyUnits) {
   346	      if (probeLazy(unit, className) && !libraries.contains(unit)) {
   347	        libraries.add(unit);
   348	      }
   349	    }
   350	    libraries.sort(Comparator.comparingInt(ContextUnit::getOriginIndex));
   351	    return libraries;
   352	  }
