   354	  private boolean probeLazy(ContextUnit unit, String className) {
   355	    Map<String, byte[]> probes = this.lazyProbes.computeIfAbsent(unit, ignored -> new HashMap<>());
   356	    byte[] cached = probes.get(className);
   357	    if (cached != null) {
   358	      return cached != MISSING_BYTES;
   359	    }
   360	    try {
   361	      byte[] bytes = unit.getClassBytes(className);
   362	      probes.put(className, bytes == null ? MISSING_BYTES : bytes);
   363	      if (bytes != null) {
   364	        this.classBytes.computeIfAbsent(unit, ignored -> new HashMap<>()).put(className, bytes);
   365	      }
   366	      return bytes != null;
   367	    } catch (IOException ex) {
   368	      String message = "Failed to probe class " + className + " in " + originName(unit);
   369	      DecompilerContext.getLogger().writeMessage(message, IFernflowerLogger.Severity.ERROR, ex);
   370	      throw new UncheckedIOException(message, ex);
   371	    }
   372	  }
