   374	  private ContextUnit selectByStrategy(String className, List<ContextUnit> candidates, @Nullable String familyRoot) {
   375	    DuplicateClassStrategy strategy = duplicateClassStrategy();
   376	    boolean differing = validateDuplicateBytes(className, candidates, familyRoot);
   377	    ContextUnit selected = strategy == DuplicateClassStrategy.LAST ? candidates.get(candidates.size() - 1) : candidates.get(0);
   378	    if (differing) {
   379	      warnDuplicate(className, candidates, selected, familyRoot);
   380	    }
   381	    return selected;
   382	  }
   383	
   384	  private boolean validateDuplicateBytes(String className, List<ContextUnit> candidates, @Nullable String familyRoot) {
   385	    if (candidates.size() < 2) {
   386	      return false;
   387	    }
   388	    byte[] first = requireClassBytes(candidates.get(0), className);
   389	    boolean differing = false;
   390	    for (int i = 1; i < candidates.size(); i++) {
   391	      if (!Arrays.equals(first, requireClassBytes(candidates.get(i), className))) {
   392	        differing = true;
   393	      }
   394	    }
   395	    if (differing && duplicateClassStrategy() == DuplicateClassStrategy.ERROR) {
   396	      throw new IllegalStateException("Conflicting duplicate class " + className + " for strategy error in highest-precedence origins: " +
   397	        joinOrigins(candidates) + "; metadata family root: " + displayFamilyRoot(familyRoot));
   398	    }
   399	    return differing;
   400	  }
