   402	  private void warnIfDiffering(String className, List<ContextUnit> candidates, ContextUnit selected, String familyRoot) {
   403	    if (duplicateClassStrategy() != DuplicateClassStrategy.ERROR && validateDuplicateBytes(className, candidates, familyRoot)) {
   404	      warnDuplicate(className, candidates, selected, familyRoot);
   405	    }
