   408	  private void warnDuplicate(String className, List<ContextUnit> candidates, ContextUnit selected, @Nullable String familyRoot) {
   409	    List<ContextUnit> ignored = candidates.stream().filter(candidate -> candidate != selected).toList();
   410	    DecompilerContext.getLogger().writeMessage(
