   471	  private static Set<String> connectedFamily(Map<String, Set<String>> graph, String start) {
   472	    Set<String> result = new LinkedHashSet<>();
   473	    Deque<String> pending = new ArrayDeque<>();
   474	    pending.add(start);
   475	    while (!pending.isEmpty()) {
   476	      String current = pending.removeFirst();
   477	      if (result.add(current)) {
   478	        pending.addAll(graph.getOrDefault(current, Set.of()));
   479	      }
   480	    }
   481	    return result;
   482	  }
